(function(){function QRCode(el,options){var container=(typeof el==='string')?document.getElementById(el):el;if(!container)return;var text=(options&&options.text)||window.location.href;var width=(options&&options.width)||(options&&options.height)||200;var height=(options&&options.height)||width;var img=document.createElement('img');img.alt=(options&&options.altText)||('QR code for '+text);img.setAttribute('aria-label',img.alt);img.width=width;img.height=height;img.src='https://api.qrserver.com/v1/create-qr-code/?size='+width+'x'+height+'&data='+encodeURIComponent(text);container.innerHTML='';container.appendChild(img);}QRCode.CorrectLevel=QRCode.CorrectLevel||{L:1,M:0,Q:2,H:3};window.QRCode=QRCode;})();
